#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct coppia {
    char *chiave;
    char *valore;
} coppia_t;

int estrai_coppia(const char **cursore, char chiave_out[32], char valore_out[32]);
bool aggiungi_coppia(coppia_t **tab, size_t *len, size_t *cap, const char *chiave, const char *valore);
void scambia_puntatori(char **a, char **b);
void libera_tabella(coppia_t **tab, size_t *len, size_t *cap);

int main(void) {
    char riga[256], extra = '\0';
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr) {
        fprintf(stderr, "Errore: input mancante.\n");
        return EXIT_FAILURE;
    }
    riga[strcspn(riga, "\r\n")] = '\0';

    coppia_t *tabella = nullptr;
    size_t len = 0, cap = 0;
    const char *cursore = riga;
    char k[32], v[32];
    int esito = 0;
    while ((esito = estrai_coppia(&cursore, k, v)) == 1) {
        if (!aggiungi_coppia(&tabella, &len, &cap, k, v)) {
            libera_tabella(&tabella, &len, &cap);
            fprintf(stderr, "Errore: memoria esaurita.\n");
            return EXIT_FAILURE;
        }
    }
    if (esito == -1) {
        libera_tabella(&tabella, &len, &cap);
        fprintf(stderr, "Errore: sintassi coppia non valida.\n");
        return EXIT_FAILURE;
    }
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        char cmd[16];
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        size_t i = 0, j = 0;
        if (strcmp(cmd, "SWAP") == 0 && sscanf(riga, "SWAP %zu %zu %c", &i, &j, &extra) == 2 &&
            i < len && j < len) {
            scambia_puntatori(&tabella[i].valore, &tabella[j].valore);
        } else {
            libera_tabella(&tabella, &len, &cap);
            fprintf(stderr, "Errore: comando SWAP non valido.\n");
            return EXIT_FAILURE;
        }
    }
    for (size_t i = 0; i < len; ++i) {
        printf("[%zu] %s=%s\n", i, tabella[i].chiave, tabella[i].valore);
    }
    printf("Totale coppie: %zu (capacita: %zu)\n", len, cap);
    libera_tabella(&tabella, &len, &cap);
    printf("Dopo rilascio: ptr_nullo=%d len=%zu cap=%zu\n", tabella == nullptr, len, cap);
    return EXIT_SUCCESS;
}

int estrai_coppia(const char **cursore, char chiave_out[32], char valore_out[32]) {
    if (cursore == nullptr || *cursore == nullptr) { return -1; }
    const char *p = *cursore;
    while (*p == ' ' || *p == '\t' || *p == ';') { ++p; }
    if (*p == '\0') { *cursore = p; return 0; }
    size_t lk = 0;
    while (*p != '\0' && *p != '=' && *p != ';' && *p != ' ' && *p != '\t') {
        if (lk >= 31) { return -1; }
        chiave_out[lk++] = *p++;
    }
    chiave_out[lk] = '\0';
    if (lk == 0 || *p != '=') { return -1; }
    ++p;
    size_t lv = 0;
    while (*p != '\0' && *p != '=' && *p != ';' && *p != ' ' && *p != '\t') {
        if (lv >= 31) { return -1; }
        valore_out[lv++] = *p++;
    }
    valore_out[lv] = '\0';
    if (lv == 0 || (*p != '\0' && *p != ';' && *p != ' ' && *p != '\t')) { return -1; }
    *cursore = p;
    return 1;
}

bool aggiungi_coppia(coppia_t **tab, size_t *len, size_t *cap, const char *chiave, const char *valore) {
    if (tab == nullptr || len == nullptr || cap == nullptr) { return false; }
    if (*len == *cap) {
        size_t ncap = (*cap == 0) ? 2 : (*cap * 2);
        coppia_t *tmp = realloc(*tab, ncap * sizeof(*tmp));
        if (tmp == nullptr) { return false; }
        *tab = tmp;
        *cap = ncap;
    }
    char *ck = strdup(chiave);
    char *cv = strdup(valore);
    if (ck == nullptr || cv == nullptr) {
        free(ck);
        free(cv);
        return false;
    }
    (*tab)[*len] = (coppia_t){.chiave = ck, .valore = cv};
    ++(*len);
    return true;
}

void scambia_puntatori(char **a, char **b) {
    if (a != nullptr && b != nullptr) {
        char *tmp = *a;
        *a = *b;
        *b = tmp;
    }
}

void libera_tabella(coppia_t **tab, size_t *len, size_t *cap) {
    if (tab != nullptr && *tab != nullptr) {
        for (size_t i = 0; i < *len; ++i) {
            free((*tab)[i].chiave);
            free((*tab)[i].valore);
        }
        free(*tab);
        *tab = nullptr;
    }
    if (len != nullptr) { *len = 0; }
    if (cap != nullptr) { *cap = 0; }
}

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct matrice_contigua {
    size_t righe;
    size_t cols;
    int *dati;
} matrice_contigua_t;

bool crea_contigua(matrice_contigua_t *m, size_t r, size_t c);
void libera_contigua(matrice_contigua_t *m);
bool trasponi_contigua(const matrice_contigua_t *src, matrice_contigua_t *dst);
int **crea_per_righe(size_t r, size_t c);
void libera_per_righe(int **m, size_t r);
long long somma_riga(const int *riga, size_t c);
void ordina_righe_per_somma(int **m, size_t r, size_t c);

int main(void) {
    char riga[512], extra = '\0';
    int r_in = 0, c_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %c", &r_in, &c_in, &extra) != 2 ||
        r_in < 1 || r_in > 32 || c_in < 1 || c_in > 32) {
        fprintf(stderr, "Errore: dimensioni matrice non valide.\n");
        return EXIT_FAILURE;
    }
    size_t r = (size_t)r_in, c = (size_t)c_in;
    matrice_contigua_t orig = {}, trasp = {};
    int **per_righe = crea_per_righe(r, c);
    if (!crea_contigua(&orig, r, c) || per_righe == nullptr) {
        libera_contigua(&orig);
        libera_per_righe(per_righe, r);
        fprintf(stderr, "Errore: allocazione fallita.\n");
        return EXIT_FAILURE;
    }
    for (size_t i = 0; i < r; ++i) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr) {
            libera_contigua(&orig); libera_per_righe(per_righe, r);
            fprintf(stderr, "Errore: riga mancante.\n");
            return EXIT_FAILURE;
        }
        const char *p = riga;
        for (size_t j = 0; j < c; ++j) {
            int val = 0, letti = 0;
            if (sscanf(p, "%d%n", &val, &letti) != 1) {
                libera_contigua(&orig); libera_per_righe(per_righe, r);
                fprintf(stderr, "Errore: valore intero non valido.\n");
                return EXIT_FAILURE;
            }
            orig.dati[i * c + j] = val;
            per_righe[i][j] = val;
            p += letti;
        }
        if (sscanf(p, " %c", &extra) == 1) {
            libera_contigua(&orig); libera_per_righe(per_righe, r);
            fprintf(stderr, "Errore: dati in eccesso sulla riga.\n");
            return EXIT_FAILURE;
        }
    }
    if (!trasponi_contigua(&orig, &trasp)) {
        libera_contigua(&orig); libera_per_righe(per_righe, r);
        return EXIT_FAILURE;
    }
    printf("Trasposta (%zux%zu):\n", trasp.righe, trasp.cols);
    for (size_t i = 0; i < trasp.righe; ++i) {
        for (size_t j = 0; j < trasp.cols; ++j) {
            printf("%s%d", (j > 0) ? " " : "", trasp.dati[i * trasp.cols + j]);
        }
        printf("\n");
    }
    ordina_righe_per_somma(per_righe, r, c);
    printf("Righe ordinate per somma:\n");
    for (size_t i = 0; i < r; ++i) {
        for (size_t j = 0; j < c; ++j) {
            printf("%s%d", (j > 0) ? " " : "", per_righe[i][j]);
        }
        printf(" (somma=%lld)\n", somma_riga(per_righe[i], c));
    }
    libera_contigua(&orig);
    libera_contigua(&trasp);
    libera_per_righe(per_righe, r);
    return EXIT_SUCCESS;
}

bool crea_contigua(matrice_contigua_t *m, size_t r, size_t c) {
    if (m == nullptr || r == 0 || c == 0 || r > SIZE_MAX / c) { return false; }
    int *d = calloc(r * c, sizeof(*d));
    if (d == nullptr) { return false; }
    m->righe = r; m->cols = c; m->dati = d;
    return true;
}

void libera_contigua(matrice_contigua_t *m) {
    if (m != nullptr) { free(m->dati); m->dati = nullptr; m->righe = 0; m->cols = 0; }
}

bool trasponi_contigua(const matrice_contigua_t *src, matrice_contigua_t *dst) {
    if (!crea_contigua(dst, src->cols, src->righe)) { return false; }
    for (size_t i = 0; i < src->righe; ++i) {
        for (size_t j = 0; j < src->cols; ++j) {
            dst->dati[j * dst->cols + i] = src->dati[i * src->cols + j];
        }
    }
    return true;
}

int **crea_per_righe(size_t r, size_t c) {
    if (r == 0 || c == 0) { return nullptr; }
    int **m = calloc(r, sizeof(*m));
    if (m == nullptr) { return nullptr; }
    for (size_t i = 0; i < r; ++i) {
        m[i] = calloc(c, sizeof(*m[i]));
        if (m[i] == nullptr) {
            libera_per_righe(m, i);
            return nullptr;
        }
    }
    return m;
}

void libera_per_righe(int **m, size_t r) {
    if (m == nullptr) { return; }
    for (size_t i = 0; i < r; ++i) { free(m[i]); }
    free(m);
}

long long somma_riga(const int *riga, size_t c) {
    long long s = 0;
    for (size_t j = 0; j < c; ++j) { s += riga[j]; }
    return s;
}

void ordina_righe_per_somma(int **m, size_t r, size_t c) {
    for (size_t i = 1; i < r; ++i) {
        int *chiave = m[i];
        long long s_chiave = somma_riga(chiave, c);
        size_t j = i;
        while (j > 0 && somma_riga(m[j - 1], c) > s_chiave) {
            m[j] = m[j - 1];
            --j;
        }
        m[j] = chiave;
    }
}

#include <ctype.h>
#include <errno.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int parsa_long(const char *s, int base, long *out);
bool parsa_double(const char *s, double *out);
int esegui_comando(int argc, char *argv[]);

int main(int argc, char *argv[]) {
    if (argc > 1) {
        return (esegui_comando(argc, argv) == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
    }
    char riga[512];
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        riga[strcspn(riga, "\r\n")] = '\0';
        char prog[] = "cli";
        char *args[33];
        int n = 0;
        args[n++] = prog;
        char *p = riga;
        while (*p != '\0' && n < 32) {
            while (*p != '\0' && isspace((unsigned char)*p)) { ++p; }
            if (*p == '\0') { break; }
            args[n++] = p;
            while (*p != '\0' && !isspace((unsigned char)*p)) { ++p; }
            if (*p != '\0') { *p++ = '\0'; }
        }
        args[n] = nullptr;
        if (n > 1) {
            esegui_comando(n, args);
        }
    }
    return EXIT_SUCCESS;
}

int parsa_long(const char *s, int base, long *out) {
    if (s == nullptr || *s == '\0' || isspace((unsigned char)*s)) { return 1; }
    char *end = nullptr;
    errno = 0;
    long val = strtol(s, &end, base);
    if (end == s || *end != '\0') { return 1; }
    if (errno == ERANGE) { return 2; }
    *out = val;
    return 0;
}

bool parsa_double(const char *s, double *out) {
    if (s == nullptr || *s == '\0' || isspace((unsigned char)*s)) { return false; }
    char *end = nullptr;
    errno = 0;
    double val = strtod(s, &end);
    if (end == s || *end != '\0' || errno == ERANGE) { return false; }
    if (val != val || fabs(val) == HUGE_VAL) { return false; }
    *out = val;
    return true;
}

int esegui_comando(int argc, char *argv[]) {
    int base = 10;
    double scala = 1.0;
    int validi = 0, scartati = 0;
    long long somma = 0;
    for (int i = 1; i < argc && argv[i] != nullptr; ++i) {
        if (strcmp(argv[i], "--base") == 0) {
            long b = 0;
            if (i + 1 >= argc || parsa_long(argv[i + 1], 10, &b) != 0 ||
                (b != 0 && b != 2 && b != 8 && b != 10 && b != 16)) {
                printf("ERRORE OPZIONE: --base\n");
                return 1;
            }
            base = (int)b;
            ++i;
        } else if (strcmp(argv[i], "--scala") == 0) {
            if (i + 1 >= argc || !parsa_double(argv[i + 1], &scala)) {
                printf("ERRORE OPZIONE: --scala\n");
                return 1;
            }
            ++i;
        } else if (argv[i][0] == '-' && argv[i][1] == '-') {
            printf("ERRORE OPZIONE: %s\n", argv[i]);
            return 1;
        } else {
            long v = 0;
            int err = parsa_long(argv[i], base, &v);
            if (err == 0) {
                somma += v;
                ++validi;
            } else {
                ++scartati;
                printf("SCARTATO: %s (%s)\n", argv[i], (err == 2) ? "overflow" : "formato");
            }
        }
    }
    printf("RISULTATO -> base=%d scala=%.2f validi=%d scartati=%d somma=%lld scalata=%.2f\n",
           base, scala, validi, scartati, somma, (double)somma * scala);
    return 0;
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

bool fette_sovrapposte(size_t off_a, size_t off_b, size_t len);
void media_mobile_restrict(double *restrict dst, const double *restrict src, size_t n);
bool applica_filtro(double *buf, size_t cap, size_t off_dst, size_t off_src, size_t len, bool *usato_tmp);
double energia_fette(const double *const *fette, const size_t *lunghezze, size_t k);

int main(void) {
    char riga[512], cmd[16], extra = '\0';
    int cap_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &cap_in, &extra) != 1 || cap_in < 1 || cap_in > 100) {
        fprintf(stderr, "Errore: capacita non valida.\n");
        return EXIT_FAILURE;
    }
    size_t cap = (size_t)cap_in;
    double *buf = calloc(cap, sizeof(*buf));
    if (buf == nullptr) { return EXIT_FAILURE; }
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr) {
        free(buf);
        fprintf(stderr, "Errore: campioni mancanti.\n");
        return EXIT_FAILURE;
    }
    const char *p = riga;
    for (size_t i = 0; i < cap; ++i) {
        int letti = 0;
        if (sscanf(p, "%lf%n", &buf[i], &letti) != 1) {
            free(buf);
            fprintf(stderr, "Errore: campione non valido.\n");
            return EXIT_FAILURE;
        }
        p += letti;
    }
    if (sscanf(p, " %c", &extra) == 1) {
        free(buf);
        fprintf(stderr, "Errore: campioni in eccesso.\n");
        return EXIT_FAILURE;
    }
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        size_t dst = 0, src = 0, len = 0;
        bool usato_tmp = false;
        if (strcmp(cmd, "FILTRA") != 0 ||
            sscanf(riga, "FILTRA %zu %zu %zu %c", &dst, &src, &len, &extra) != 3 ||
            !applica_filtro(buf, cap, dst, src, len, &usato_tmp)) {
            free(buf);
            fprintf(stderr, "Errore: comando FILTRA non valido.\n");
            return EXIT_FAILURE;
        }
        printf("FILTRA [%zu..+%zu] -> [%zu..+%zu] (tmp=%s)\n",
               src, len, dst, len, usato_tmp ? "si" : "no");
    }
    printf("Buffer:");
    for (size_t i = 0; i < cap; ++i) { printf(" %.2f", buf[i]); }
    printf("\n");
    size_t meta = cap / 2;
    const double *fette[2] = {buf, buf + meta};
    size_t lun[2] = {meta, cap - meta};
    printf("Energia totale: %.2f\n", energia_fette(fette, lun, 2));
    free(buf);
    return EXIT_SUCCESS;
}

bool fette_sovrapposte(size_t off_a, size_t off_b, size_t len) {
    return (off_a < off_b + len) && (off_b < off_a + len);
}

void media_mobile_restrict(double *restrict dst, const double *restrict src, size_t n) {
    if (n == 1) {
        dst[0] = src[0];
        return;
    }
    dst[0] = (src[0] + src[1]) / 2.0;
    for (size_t i = 1; i + 1 < n; ++i) {
        dst[i] = (src[i - 1] + src[i] + src[i + 1]) / 3.0;
    }
    dst[n - 1] = (src[n - 2] + src[n - 1]) / 2.0;
}

bool applica_filtro(double *buf, size_t cap, size_t off_dst, size_t off_src, size_t len, bool *usato_tmp) {
    if (buf == nullptr || usato_tmp == nullptr || len == 0 || len > cap ||
        off_dst > cap - len || off_src > cap - len) {
        return false;
    }
    if (!fette_sovrapposte(off_dst, off_src, len)) {
        *usato_tmp = false;
        media_mobile_restrict(buf + off_dst, buf + off_src, len);
        return true;
    }
    double *tmp = malloc(len * sizeof(*tmp));
    if (tmp == nullptr) { return false; }
    media_mobile_restrict(tmp, buf + off_src, len);
    for (size_t i = 0; i < len; ++i) {
        buf[off_dst + i] = tmp[i];
    }
    free(tmp);
    *usato_tmp = true;
    return true;
}

double energia_fette(const double *const *fette, const size_t *lunghezze, size_t k) {
    double somma = 0.0;
    for (size_t j = 0; j < k; ++j) {
        for (size_t i = 0; i < lunghezze[j]; ++i) {
            somma += fette[j][i] * fette[j][i];
        }
    }
    return somma;
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct elenco {
    char **voci;
    bool ha_evid;
    size_t idx_evid;
} elenco_t;

size_t conta_voci(char *const *voci);
bool aggiungi_voce(elenco_t *e, const char *testo);
bool rimuovi_voce(elenco_t *e, size_t pos);
void libera_elenco(elenco_t *e);

int main(void) {
    elenco_t e = {};
    char riga[128], cmd[16], parola[32], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        size_t idx = 0;
        if (strcmp(cmd, "ADD") == 0 && sscanf(riga, "ADD %31s %c", parola, &extra) == 1) {
            if (!aggiungi_voce(&e, parola)) {
                libera_elenco(&e);
                fprintf(stderr, "Errore: memoria esaurita.\n");
                return EXIT_FAILURE;
            }
        } else if (strcmp(cmd, "MARK") == 0 && sscanf(riga, "MARK %zu %c", &idx, &extra) == 1) {
            if (idx < conta_voci(e.voci)) {
                e.ha_evid = true;
                e.idx_evid = idx;
            } else {
                printf("MARK non valido\n");
            }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %zu %c", &idx, &extra) == 1) {
            if (!rimuovi_voce(&e, idx)) {
                printf("DEL non valido\n");
            }
        } else if (strcmp(cmd, "LIST") == 0 && sscanf(riga, "LIST %c", &extra) != 1) {
            size_t n = conta_voci(e.voci);
            if (n == 0) {
                printf("(vuoto)\n");
            } else {
                for (size_t i = 0; e.voci[i] != nullptr; ++i) {
                    printf("[%zu] %s%s\n", i, e.voci[i],
                           (e.ha_evid && e.idx_evid == i) ? " *" : "");
                }
            }
        } else {
            libera_elenco(&e);
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    size_t tot = conta_voci(e.voci);
    printf("Totale finale: %zu\n", tot);
    printf("Evidenziata: %s\n", e.ha_evid ? e.voci[e.idx_evid] : "nessuna");
    libera_elenco(&e);
    printf("Puntatore azzerato: %d\n", e.voci == nullptr);
    return EXIT_SUCCESS;
}

size_t conta_voci(char *const *voci) {
    if (voci == nullptr) { return 0; }
    size_t n = 0;
    while (voci[n] != nullptr) { ++n; }
    return n;
}

bool aggiungi_voce(elenco_t *e, const char *testo) {
    if (e == nullptr || testo == nullptr) { return false; }
    size_t n = conta_voci(e->voci);
    char *copia = strdup(testo);
    if (copia == nullptr) { return false; }
    char **tmp = realloc(e->voci, (n + 2) * sizeof(*tmp));
    if (tmp == nullptr) {
        free(copia);
        return false;
    }
    e->voci = tmp;
    e->voci[n] = copia;
    e->voci[n + 1] = nullptr;
    return true;
}

bool rimuovi_voce(elenco_t *e, size_t pos) {
    if (e == nullptr || e->voci == nullptr) { return false; }
    size_t n = conta_voci(e->voci);
    if (pos >= n) { return false; }
    free(e->voci[pos]);
    for (size_t i = pos; i < n; ++i) {
        e->voci[i] = e->voci[i + 1];
    }
    if (e->ha_evid) {
        if (e->idx_evid == pos) {
            e->ha_evid = false;
            e->idx_evid = 0;
        } else if (e->idx_evid > pos) {
            --e->idx_evid;
        }
    }
    return true;
}

void libera_elenco(elenco_t *e) {
    if (e == nullptr) { return; }
    if (e->voci != nullptr) {
        for (size_t i = 0; e->voci[i] != nullptr; ++i) {
            free(e->voci[i]);
        }
        free(e->voci);
        e->voci = nullptr;
    }
    e->ha_evid = false;
    e->idx_evid = 0;
}
